function validate(input) {
  const [{ Accounts = [], Transactions = [] }] = input;
  const accounts = new Set(), ids = new Set();
  for (const [id, limit] of Accounts) {
    if (id === null || limit === null) return 'Every account needs an id and a max_income.';
    if (accounts.has(id)) return `account_id ${id} appears twice in Accounts.`;
    accounts.add(id);
  }
  for (const [id, account, type, amount, day] of Transactions) {
    if (id === null) return 'Every transaction needs an id.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (!accounts.has(account)) return `Account ${account} is not in Accounts.`;
    if (type !== 'Creditor' && type !== 'Debtor') return `Unknown type ${type}.`;
    if (amount === null || amount <= 0) return `Transaction ${id} needs a positive amount.`;
    if (day === null || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(day)) return `day ${day} must look like 2021-06-02 11:38:14.`;
  }
  return null;
}

