function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const accountCount = small ? Math.floor(rand() * 4) : 200;
  const Accounts = [];
  for (let id = 1; id <= accountCount; id++) Accounts.push([id, small ? pick([100, 200, 300]) : 500 + 100 * Math.floor(rand() * 20)]);
  const Transactions = [];
  if (Accounts.length) {
    // Small cases stay inside a few months around a year boundary, on month edges, so sums tie limits and months touch.
    const months = small ? [[2020, 11], [2020, 12], [2021, 1], [2021, 2], [2021, 4]] : [];
    if (!small) for (let y = 2019; y <= 2021; y++) for (let m = 1; m <= 12; m++) months.push([y, m]);
    const count = small ? Math.floor(rand() * 9) : 2000;
    for (let i = 1; i <= count; i++) {
      const [y, m] = pick(months);
      const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
      const d = small ? pick([1, 15, last]) : 1 + Math.floor(rand() * last);
      const time = `${pad(Math.floor(rand() * 24))}:${pad(Math.floor(rand() * 60))}:${pad(Math.floor(rand() * 60))}`;
      Transactions.push([
        i,
        pick(Accounts)[0],
        rand() < 0.75 ? 'Creditor' : 'Debtor',
        small ? pick([50, 100, 150, 200, 250]) : 50 + Math.floor(rand() * 1500),
        `${y}-${pad(m)}-${pad(d)} ${time}`,
      ]);
    }
  }
  return [{ Accounts, Transactions }];
}
